const aiOutputString = $('AI Agent5').first().json.output;

let aiData;
try {
  const cleaned = aiOutputString
    .replace(/```json/g, '')
    .replace(/```/g, '')
    .trim();
  aiData = JSON.parse(cleaned);
} catch (e) {
  throw new Error('AI Output parse failed: ' + aiOutputString);
}

if (!aiData.customerName) {
  throw new Error('No customer name extracted from PDF: ' + JSON.stringify(aiData));
}

return {
  json: {
    customerName: aiData.customerName || '',
    invoiceNumber: aiData.invoiceNumber || 'INV-001',
    invoiceDate: aiData.invoiceDate || '2025-01-01',
    dueDate: aiData.dueDate || '2025-01-31',
    customerTotal: aiData.customerTotal || 0,
    lineItems: aiData.lineItems || []
  }
};

