const customerName = $json.customerName;
const allCustomers = $items('Search QB Customer');

// Find existing customer with matching name
const match = allCustomers.find(c => {
  const qbName = (c.json.DisplayName || '').replace(/"/g, '').trim().toLowerCase();
  return qbName === customerName.trim().toLowerCase();
});

// Prefer existing customer over newly created
let customerId;
if (match) {
  customerId = match.json.Id;
} else if ($json.Id) {
  customerId = $json.Id;
} else {
  throw new Error('No customer ID found for: ' + customerName);
}

if (!customerId) {
  throw new Error('Could not resolve QB customer ID for: ' + customerName);
}

const lineItems = $('Parse AI Output').first().json.lineItems || [];

const qbLines = lineItems.map(item => ({
  "Amount": Number(item.Amount),
  "Description": String(item.Description),
  "DetailType": "SalesItemLineDetail",
  "SalesItemLineDetail": {
    "Qty": Number(item.Quantity),
    "UnitPrice": Number(item.UnitPrice),
    "ItemRef": { "value": "1" }
  }
}));

return {
  json: {
    customerName: customerName,
    customerId: customerId.toString(),
    invoiceNumber: $('Parse AI Output').first().json.invoiceNumber,
    invoiceDate: $('Parse AI Output').first().json.invoiceDate,
    dueDate: $('Parse AI Output').first().json.dueDate,
    customerTotal: $('Parse AI Output').first().json.customerTotal,
    qbLines: qbLines
  }
};
